      return <button key={i} className={"qz-opt" + cls} onClick={() => set(p.id, i)} aria-label={`Option ${o.letter}`}><span className="qz-lt">{o.letter}</span><ModelSketch W={380} H={230} compact model={model} res={o.res} diagram={p.kind} flip={o.flip} flipMembers={o.flipMembers || []} showLoads={false} showDims={false} /><div className="qz-why">{revealed ? i === p.expected ? "✓ correct" : `✗ ${o.label}` : ""}</div></button>;
