var prefersReducedMotion = () => typeof window !== "undefined" && !!window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
var springy = (k) => {
  const c1 = 1.4, c3 = c1 + 1;
  return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);
};
function useGrow(trigger, ms = 720) {
  const [p, setP] = useState(prefersReducedMotion() ? 1 : 0);
  useEffect(() => {
    if (prefersReducedMotion()) {
      setP(1);
      return void 0;
    }
    let raf, t0 = null;
    const step = (t) => {
      if (t0 === null) t0 = t;
      const k = Math.min(1, (t - t0) / ms);
      setP(springy(k));
      if (k < 1) raf = requestAnimationFrame(step);
    };
    setP(0);
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [trigger, ms]);
  return p;
}
function useCycle(on, period = 2600) {
  const [p, setP] = useState(1);
  const live = useRef(on);
  live.current = on;
  useEffect(() => {
    if (!on || prefersReducedMotion()) {
      setP(1);
      return void 0;
    }
    let raf;
    const t0 = performance.now();
    const step = (t) => {
      if (!live.current) return;
      const ph = (t - t0) % period / period;
      setP((1 - Math.cos(2 * Math.PI * ph)) / 2);
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [on, period]);
  return p;
}
