  const narrow = useNarrow2();
  const [archCfg, setArchCfg] = useState({ span: 12, rise: 3.5, segs: 12, profile: "parabola", support: "pin", threePin: false });
  const [rMode, setRMode] = useState("values");
  const [animKey, setAnimKey] = useState(0);
